  # issue #121: 0.9 > 0.5 also trips the D6 soft warning (valid only for inbred
  # pairs) before the strict stop. Assert it instead of leaking it; the frame is
  # validated on more than one pass, so the warning count is not pinned.
  warns <- character()
  expect_error(
    withCallingHandlers(
      suppressMessages(gvaConvergence(fx$ped,
        pop = fx$pop, nMax = 800L, seed = 11L, kinshipOverrides = badVal
      )),
      warning = function(w) {
        warns <<- c(warns, conditionMessage(w))
        invokeRestart("muffleWarning")
      }
    ),
    "above the maximum"
  )
  expect_gte(length(warns), 1L)
  expect_true(all(grepl("> 0.5", warns, fixed = TRUE)))
})

